/* ---------- batch nine ---------- */
.ev-b{--c:#5d9bfb;--cb:rgba(93,155,251,.1);--cl:rgba(93,155,251,.35)}
.ev-m{--c:#3ecf8e;--cb:rgba(62,207,142,.1);--cl:rgba(62,207,142,.35)}
.ev-r{--c:#ff5a5f;--cb:rgba(255,90,95,.1);--cl:rgba(255,90,95,.35)}
.ev-l{--c:#a993ff;--cb:rgba(169,147,255,.12);--cl:rgba(169,147,255,.38)}
.ec-tag{display:inline-flex;align-items:center;gap:6px;padding:3px 9px;border:1px solid var(--line);font-size:12px;font-weight:600;color:var(--text-dim);transition:opacity .25s,background-color .25s,border-color .25s}
.ec-tag i{width:7px;height:7px;flex:none;background:var(--c)}

/* event calendar */
.ec{position:relative;width:100%;max-width:360px;padding:12px;overflow:visible!important}
.ec-tags{display:flex;flex-wrap:wrap;gap:6px;margin:2px 0 12px}
.ec-tags .ec-tag{cursor:pointer}
.ec-tags .ec-tag.off{opacity:.4}
.ec-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:2px;transition:opacity .2s ease,transform .3s var(--ease)}
.ec-grid.out-l{opacity:0;transform:translateX(-14px)}
.ec-grid.out-r{opacity:0;transform:translateX(14px)}
.ec-d{position:relative;height:42px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;font-size:13px;color:var(--text);transition:background-color .2s,color .2s,box-shadow .2s}
.ec-d:hover{background:rgba(var(--fg-rgb),.05)}
.ec-d.mute{color:var(--muted);opacity:.5}
.ec-d.today .n{color:var(--accent);font-weight:700}
.ec-d.sel{background:var(--accent-hi);color:#120a02}
.ec-d.sel.today .n{color:inherit}
.ec-dots{display:flex;gap:3px;height:5px}
.ec-dots i{width:5px;height:5px;background:var(--c);transition:opacity .25s,transform .3s var(--ease)}
.ec-dots i.off{opacity:0;transform:scale(0)}
.ec-pop{position:absolute;z-index:6;width:300px;padding:14px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 22px 50px -20px rgba(0,0,0,.45);opacity:0;visibility:hidden;transform:scale(.92) translateY(6px);transition:opacity .2s ease,transform .4s cubic-bezier(.34,1.4,.64,1),visibility 0s linear .4s}
.ec-pop.show{opacity:1;visibility:visible;transform:none;transition:opacity .2s ease,transform .4s cubic-bezier(.34,1.4,.64,1),visibility 0s}
.ec-pop-h{display:flex;align-items:center;justify-content:space-between;gap:8px}
.ec-acts{display:flex;gap:2px}
.ec-acts button{width:28px;height:28px;display:grid;place-items:center;color:var(--muted);transition:color .2s,background-color .2s}
.ec-acts button:hover{color:var(--text);background:var(--chip)}
.ec-pop-t{margin:10px 0 8px;font-size:16px;font-weight:600;letter-spacing:-.01em}
.ec-meta{display:flex;flex-direction:column;gap:5px;font-size:13px;color:var(--text-dim)}
.ec-meta span{display:flex;align-items:center;gap:8px}
.ec-meta .ms{color:var(--muted)}
.ec-guests{display:flex;align-items:center;gap:0;margin:14px 0 8px}
.ec-guests .dz-av{width:30px;height:30px;margin-left:-7px;border-radius:50%;box-shadow:0 0 0 2px var(--panel)}
.ec-guests .dz-av:first-child{margin-left:0}
.ec-add{width:30px;height:30px;margin-left:6px;display:grid;place-items:center;border-radius:50%;border:1px dashed var(--icon-line);color:var(--muted);transition:color .2s,border-color .2s}
.ec-add:hover{color:var(--text);border-color:var(--text-dim)}
.ec-rsvp{display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--text-dim)}
.ec-rsvp b{color:var(--text);font-weight:600}
.ec-rsvp i{width:1px;height:12px;background:var(--line)}
.ec-about{margin-top:12px;padding-top:12px;border-top:1px solid var(--line);font-size:13px;line-height:1.55;color:var(--text-dim)}
.ec-about b{display:block;margin-bottom:3px;color:var(--text);font-weight:600}
.ec-pop-f{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}

/* event calendar: agenda below the month */
.ec-up{margin-top:12px;padding-top:12px;border-top:1px solid var(--line)}
.ec-uh{display:flex;justify-content:space-between;margin-bottom:6px;font-size:12px;font-weight:600;color:var(--muted)}
.ec-ui{display:flex;align-items:center;gap:10px;width:100%;padding:7px 8px;text-align:left;transition:background-color .15s}
.ec-ui:hover{background:var(--chip)}
.ec-ui i{width:8px;height:8px;flex:none;background:var(--c)}
.ec-ui .t{flex:1;min-width:0;font-size:13px;font-weight:500;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ec-ui .m{font-size:12px;color:var(--muted);white-space:nowrap}

const EVCATS = { b:'Design review', m:'Client call', r:'Deadline', l:'Workshop' };
/* ---------- event calendar ---------- */
{
  const ec = $('#ec'), grid = $('#ec-grid'), pop = $('#ec-pop'), mlab = $('#ec-month'), up = $('#ec-up');
  // demo events keyed by day of month, shown in whichever month you view
  const EV = {
    3:[{ k:'m', t:'Kickoff with Northwind', s:'10:00 to 10:45 AM', g:['Maya Chen','Oscar Lind','Priya Nair'], a:'First call with the Northwind team to agree scope, owners and the launch date.' }],
    7:[{ k:'b', t:'Pricing page review', s:'1:30 to 2:30 PM', g:['Maya Chen','Tom Becker','Joanna Kim','Jonas Weber','Ines Duarte'], a:'Walk through the new comparison table and decide which plan names we keep.' }],
    10:[{ k:'l', t:'Design system workshop', s:'9:30 to 12:00 PM', g:['Priya Nair','Oscar Lind','Sam Rivera','Joanna Kim'], a:'Hands-on session to merge the button and input variants into one token set.' },{ k:'m', t:'Weekly client sync', s:'3:00 to 3:30 PM', g:['Maya Chen','Tom Becker'], a:'Status update and next steps for the brand refresh.' }],
    14:[{ k:'r', t:'Design sign-off', s:'All day', g:['Maya Chen','Jonas Weber'], a:'Final approval on every page before development starts.' }],
    18:[{ k:'b', t:'Onboarding flow review', s:'11:00 to 12:00 PM', g:['Ines Duarte','Priya Nair','Oscar Lind'], a:'Review the shorter onboarding and the new workspace step.' }],
    22:[{ k:'m', t:'Quarterly planning call', s:'2:00 to 3:00 PM', g:['Maya Chen','Tom Becker','Sam Rivera','Joanna Kim','Jonas Weber','Ines Duarte'], a:'Plan the next quarter of design work and agree the retainer focus.' },{ k:'l', t:'Motion jam', s:'4:00 to 5:00 PM', g:['Oscar Lind','Priya Nair'], a:'Prototype the new page transitions together.' }],
    27:[{ k:'r', t:'Launch day', s:'All day', g:['Maya Chen','Oscar Lind','Priya Nair','Tom Becker'], a:'The marketing site goes live. Everyone on standby for fixes.' }]
  };
  let vy = TODAY.getFullYear(), vm = TODAY.getMonth(), sel = null, off = new Set();
  function upcoming(){
    const rows = Object.keys(EV).map(Number).sort((a, b) => a - b).flatMap(d => EV[d].map(e => ({ d, e }))).slice(0, 4);
    up.innerHTML = `<div class="ec-uh"><span>This month</span><span>${Object.values(EV).flat().length} events</span></div>` + rows.map(({ d, e }) => `<button class="ec-ui ev-${e.k}" data-d="${d}"><i></i><span class="t">${e.t}</span><span class="m">${new Date(vy, vm, d).toLocaleDateString('en-GB', { day:'numeric', month:'short' })}, ${e.s.split(' to ')[0]}</span></button>`).join('');
  }
  function build(){
    upcoming();
    mlab.textContent = new Date(vy, vm, 1).toLocaleDateString('en-GB', { month:'long', year:'numeric' });
    grid.innerHTML = monthCells(vy, vm).map(d => {
      const inM = d.getMonth() === vm, evs = inM ? (EV[d.getDate()] || []) : [];
      const cls = ['ec-d', inM ? '' : 'mute', dayKey(d) === dayKey(TODAY) ? 'today' : '', sel && dayKey(d) === dayKey(sel) ? 'sel' : ''].join(' ');
      return `<button class="${cls}" data-k="${d.getTime()}"><span class="n">${d.getDate()}</span><span class="ec-dots">${evs.map(e => `<i class="ev-${e.k} ${off.has(e.k) ? 'off' : ''}"></i>`).join('')}</span></button>`;
    }).join('');
  }
  function card(d, evs, idx){
    const e = evs[idx], yes = Math.max(1, e.g.length - 1);
    return `<div class="enter">
      <div class="ec-pop-h"><span class="ec-tag ev-${e.k}"><i></i>${EVCATS[e.k]}</span><div class="ec-acts">${evs.length > 1 ? `<button data-a="next" aria-label="Next event">${ic('chevron_right','sm')}</button>` : ''}<button data-a="dup" aria-label="Duplicate">${ic('content_copy','sm')}</button><button data-a="edit" aria-label="Edit">${ic('edit_note','sm')}</button><button data-a="close" aria-label="Close">${ic('close','sm')}</button></div></div>
      <div class="ec-pop-t">${e.t}</div>
      <div class="ec-meta"><span>${ic('calendar','sm')}${d.toLocaleDateString('en-GB', { weekday:'long', day:'numeric', month:'long' })}</span><span>${ic('schedule','sm')}${e.s}</span></div>
      <div class="ec-guests">${e.g.slice(0, 5).map(n => avatar(n)).join('')}<button class="ec-add" aria-label="Add guest">${ic('add','sm')}</button></div>
      <div class="ec-rsvp"><b>${e.g.length} guests</b><i></i>${yes} yes<i></i>${e.g.length - yes} awaiting</div>
      <div class="ec-about"><b>About this event</b>${e.a}</div>
      <div class="ec-pop-f"><button class="btn" data-a="maybe">Maybe</button><button class="btn primary" data-a="join">Join call</button></div>
    </div>`;
  }
  let curEvs = [], curIdx = 0, curDay = null;
  function openPop(btn, d){
    curEvs = (EV[d.getDate()] || []).filter(e => !off.has(e.k)); curIdx = 0; curDay = d;
    if (!curEvs.length){ pop.classList.remove('show'); return; }
    pop.innerHTML = card(d, curEvs, 0);
    const er = ec.getBoundingClientRect(), br = btn.getBoundingClientRect(), w = 300;
    const left = Math.max(-20, Math.min(er.width - w + 20, br.left - er.left + br.width / 2 - w / 2));
    pop.style.left = left + 'px';
    pop.classList.remove('show'); pop.style.top = '0px';
    const h = pop.offsetHeight, below = br.bottom - er.top + 8;
    const top = below + h > er.height + 60 ? Math.max(-40, br.top - er.top - h - 8) : below;
    pop.style.top = top + 'px'; pop.style.transformOrigin = `${br.left - er.left - left + br.width / 2}px ${top > br.top - er.top ? '0' : '100%'}`;
    requestAnimationFrame(() => pop.classList.add('show')); Sound.play('open');
  }
  grid.addEventListener('click', e => {
    const b = e.target.closest('.ec-d'); if (!b) return; const d = new Date(+b.dataset.k);
    if (d.getMonth() !== vm) return;
    sel = d; $$('.ec-d', grid).forEach(x => x.classList.toggle('sel', x === b)); Sound.play('select');
    openPop(b, d);
  });
  pop.addEventListener('click', e => {
    const a = e.target.closest('[data-a]'); if (!a) return; const act = a.dataset.a;
    if (act === 'close'){ pop.classList.remove('show'); Sound.play('close'); }
    else if (act === 'next'){ curIdx = (curIdx + 1) % curEvs.length; pop.innerHTML = card(curDay, curEvs, curIdx); Sound.play('tab'); }
    else if (act === 'join'){ Sound.play('done'); showToast('Joining ' + curEvs[curIdx].t); pop.classList.remove('show'); }
    else { Sound.play('tick'); showToast(act === 'dup' ? 'Event duplicated' : act === 'edit' ? 'Opening the editor' : 'Marked as maybe'); }
  });
  up.addEventListener('click', e => { const b = e.target.closest('.ec-ui'); if (!b) return; const d = new Date(vy, vm, +b.dataset.d); const cell = $$('.ec-d', grid).find(x => +x.dataset.k === d.getTime()); if (!cell) return; sel = d; $$('.ec-d', grid).forEach(x => x.classList.toggle('sel', x === cell)); Sound.play('select'); openPop(cell, d); });
  const move = n => { pop.classList.remove('show'); const nm = vm + n; grid.classList.add(n > 0 ? 'out-l' : 'out-r'); setTimeout(() => { vy += Math.floor(nm / 12); vm = ((nm % 12) + 12) % 12; sel = null; build(); grid.style.transition = 'none'; grid.classList.remove('out-l', 'out-r'); grid.classList.add(n > 0 ? 'out-r' : 'out-l'); grid.offsetWidth; grid.style.transition = ''; grid.classList.remove('out-l', 'out-r'); }, 180); Sound.play('tab'); };
  $('#ec-prev').addEventListener('click', () => move(-1)); $('#ec-next').addEventListener('click', () => move(1));
  document.addEventListener('pointerdown', e => { if (pop.classList.contains('show') && !ec.contains(e.target)) pop.classList.remove('show'); });
  build();
}
